// Game logic pattern (server/client)
const make{Game}Move = (board, index, turn) => {
  if (board[index] !== null) return { valid: false };
  const newBoard = [...board];
  newBoard[index] = turn;
  const result = check{Game}Winner(newBoard);
  return { valid: true, board: newBoard, result };
};

// Board component pattern
const {Game}Board = ({ board, onCellClick, turn }) => {
  return (
    <div className="{game}-board">
      {board.map((value, index) => (
        <div key={index} className="{game}-cell" onClick={() => onCellClick(index)}>
          {/* render cell content */}
        </div>
      ))}
    </div>
  );
};

